const canvas=document.getElementById('visualCanvas');const ctx=canvas.getContext('2d',{willReadFrequently:true});let source='gradient',rig=10,armed=false,blackout=false,flashUntil=0,selected=0;const fixtures=[];for(let side=0;side<2;side++){for(let i=0;i<7;i++){fixtures.push({id:(side?'R':'L')+(i+1),x:side?0.58+i*.055:.09+i*.055,y:.76,active:true,color:[0,0,0]})}}const inactive=new Set([2,4,9,11]);function applyRig(){fixtures.forEach((f,i)=>f.active=rig===14||!inactive.has(i))}applyRig();
const sliders={intensity:document.getElementById('intensity'),speed:document.getElementById('speed'),white:document.getElementById('white'),amber:document.getElementById('amber'),uv:document.getElementById('uv')};Object.entries(sliders).forEach(([k,e])=>e.addEventListener('input',()=>document.getElementById(k+'Out').textContent=e.value+(k==='speed'?'×':'%')));
function noise(x,y,t){return .5+.5*Math.sin(x*.045+Math.sin(y*.03+t)*3+t*1.7)*Math.cos(y*.028-t*.8)}function render(t){const w=canvas.width,h=canvas.height,s=+sliders.speed.value/100;const g=ctx.createLinearGradient(0,0,w,h);if(source==='gradient'){g.addColorStop(0,'#13070e');g.addColorStop((.42+.12*Math.sin(t*.0003*s)),'#c92f2d');g.addColorStop(.72,'#5b1830');g.addColorStop(1,'#070914');ctx.fillStyle=g;ctx.fillRect(0,0,w,h)}else if(source==='wave'){ctx.fillStyle='#060a11';ctx.fillRect(0,0,w,h);for(let x=0;x<w;x+=4){const p=(Math.sin(x*.012+t*.002*s)+1)/2;ctx.fillStyle=`rgb(${8+p*25},${25+p*80},${48+p*150})`;ctx.fillRect(x,0,5,h)}}else if(source==='noise'){const img=ctx.createImageData(w/4,h/4);for(let y=0;y<h/4;y++)for(let x=0;x<w/4;x++){const n=noise(x,y,t*.001*s),i=(y*w/4+x)*4;img.data[i]=70+150*n;img.data[i+1]=10+35*n;img.data[i+2]=12+20*(1-n);img.data[i+3]=255}const temp=document.createElement('canvas');temp.width=w/4;temp.height=h/4;temp.getContext('2d').putImageData(img,0,0);ctx.imageSmoothingEnabled=true;ctx.drawImage(temp,0,0,w,h)}else{ctx.fillStyle='#8d151d';ctx.fillRect(0,0,w,h)}if(blackout){ctx.fillStyle='#000';ctx.fillRect(0,0,w,h)}if(performance.now()<flashUntil){ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h)}const intensity=+sliders.intensity.value/100;fixtures.forEach((f,i)=>{const px=Math.max(0,Math.min(w-1,Math.floor(f.x*w))),py=Math.max(0,Math.min(h-1,Math.floor(f.y*h)));const d=ctx.getImageData(px,py,1,1).data;f.color=[d[0]*intensity,d[1]*intensity,d[2]*intensity];ctx.beginPath();ctx.arc(px,py,i===selected?11:8,0,Math.PI*2);ctx.fillStyle=f.active?`rgb(${f.color.join(',')})`:'#18181d';ctx.fill();ctx.lineWidth=i===selected?3:1.5;ctx.strokeStyle=f.active?(i===selected?'#fff':'#ffffff90'):'#77778070';ctx.stroke();if(!f.active){ctx.beginPath();ctx.moveTo(px-5,py-5);ctx.lineTo(px+5,py+5);ctx.moveTo(px+5,py-5);ctx.lineTo(px-5,py+5);ctx.stroke()} });updateSemantic();requestAnimationFrame(render)}
function updateSemantic(){const f=fixtures[selected],r=Math.round(f.color[0]),g=Math.round(f.color[1]),b=Math.round(f.color[2]),white=Math.round(Math.min(r,g,b)*(+sliders.white.value/100)),amber=Math.round(Math.max(0,Math.min(r,g*1.25)-b*.25)*(+sliders.amber.value/100));document.getElementById('selectedFixture').textContent=f.id+(f.active?'':' · GHOST');document.getElementById('vD').textContent=sliders.intensity.value;document.getElementById('vR').textContent=Math.max(0,r-white);document.getElementById('vG').textContent=Math.max(0,g-white);document.getElementById('vB').textContent=Math.max(0,b-white);document.getElementById('vW').textContent=white;document.getElementById('vA').textContent=amber;document.getElementById('vUV').textContent=Math.round(255*(+sliders.uv.value/100));document.getElementById('vL').textContent=Math.round(Math.max(0,Math.min(g,(r+g)/2)-b*.2)*.2)}
canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;let best=0,dist=99;fixtures.forEach((f,i)=>{const d=(f.x-x)**2+(f.y-y)**2;if(d<dist){dist=d;best=i}});selected=best});
document.querySelectorAll('[data-rig]').forEach(b=>b.onclick=()=>{rig=+b.dataset.rig;document.querySelectorAll('[data-rig]').forEach(x=>x.classList.toggle('active',x===b));applyRig()});
function chooseSource(s){source=s;const names={gradient:'Crimson Field',wave:'Cold Wave',noise:'Infernal Noise',solid:'Deep Red'};document.getElementById('sourceTitle').textContent=names[s];document.querySelector('.inspector h2').textContent=names[s];document.querySelectorAll('[data-source]').forEach(x=>x.classList.toggle('active',x.dataset.source===s));document.querySelectorAll('[data-look]').forEach(x=>x.classList.toggle('active',x.dataset.look===s))}document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>chooseSource(b.dataset.source));document.querySelectorAll('[data-look]').forEach(b=>b.onclick=()=>chooseSource(b.dataset.look));
document.getElementById('armButton').onclick=e=>{armed=!armed;e.currentTarget.classList.toggle('armed',armed);e.currentTarget.textContent=armed?'OUTPUT ARMED':'ARM OUTPUT'};document.getElementById('blackoutButton').onpointerdown=()=>blackout=true;document.getElementById('blackoutButton').onpointerup=()=>blackout=false;document.getElementById('blackoutButton').onpointerleave=()=>blackout=false;document.getElementById('flashExecutor').onpointerdown=()=>flashUntil=performance.now()+180;
const attrs=['dimmer','strobe','red','green','blue','white','amber','uv','lime','macro','speed','reset','zoom'];function buildProfileRows(){const body=document.getElementById('profileRows');body.innerHTML='';attrs.forEach((a,i)=>{const tr=document.createElement('tr');tr.innerHTML=`<td><input type="number" min="1" max="13" value="${i+1}"></td><td><select>${attrs.map(x=>`<option ${x===a?'selected':''}>${x}</option>`).join('')}</select></td><td><select><option>${a==='reset'?'trigger':(['strobe','macro'].includes(a)?'range':'continuous')}</option><option>continuous</option><option>range</option><option>constant</option><option>trigger</option><option>ignore</option></select></td><td><input value="${a==='strobe'?'16–239':a==='reset'?'240–255':'0–255'}"></td><td><input type="number" value="${a==='zoom'?128:0}"></td>`;body.appendChild(tr)})}buildProfileRows();const dlg=document.getElementById('profileDialog');document.getElementById('profileButton').onclick=()=>dlg.showModal();
function projectData(){return{schemaVersion:'1.0.0',project:{id:'aeyla-prototype',name:'AEYLA SHOW',version:'0.12'},rig:`floor-${rig}`,output:{type:document.getElementById('outputType').value,destination:'10.10.10.20',portAddress:0,refreshHz:40},look:{source,intensity:+sliders.intensity.value/100,speed:+sliders.speed.value/100,whiteExtraction:+sliders.white.value/100,amberExtraction:+sliders.amber.value/100,uv:+sliders.uv.value/100}}}document.getElementById('exportButton').onclick=()=>{const blob=new Blob([JSON.stringify(projectData(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='AEYLA_SHOW_PROTOTYPE.json';a.click();URL.revokeObjectURL(a.href)};document.getElementById('importButton').onclick=()=>document.getElementById('importInput').click();document.getElementById('importInput').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());rig=d.rig==='floor-14'?14:10;source=d.look?.source||source;Object.keys(sliders).forEach(k=>{const key=k==='white'?'whiteExtraction':k==='amber'?'amberExtraction':k;const v=d.look?.[key];if(v!=null)sliders[k].value=Math.round(v*100)});chooseSource(source);applyRig();alert('Prototype project imported')}catch(err){alert('Invalid JSON: '+err.message)}};requestAnimationFrame(render);
